
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_acgga_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_acgga", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.689606768969110e-02, -6.587596769700223e-02, -6.441295402170147e-02, -6.231738815655921e-02, -5.932167215265953e-02, -5.505386689715228e-02, -4.901799477722081e-02, -4.064183054569777e-02, -2.967202410450674e-02, -1.787146801484522e-02, -1.294179389803892e-02, -3.877980455596890e-02, -4.629136259916672e-02, -3.261468050315338e-02, -1.686679481007485e-02, -4.243298725027493e-03, -2.603484637752787e-04, -2.683460366467546e-06, -3.197423612882254e-09, -1.456717254675886e-13]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


